import{_ as r,o as a,c as e,a5 as d}from"./chunks/framework.BBJce6hm.js";const b=JSON.parse('{"title":"Portainer 介绍","description":"","frontmatter":{},"headers":[],"relativePath":"doc-menu/service/docker/portainer/portainer-intro.md","filePath":"doc-menu/service/docker/portainer/portainer-intro.md"}'),o={name:"doc-menu/service/docker/portainer/portainer-intro.md"};function i(n,t,s,l,h,c){return a(),e("div",null,[...t[0]||(t[0]=[d(`<h1 id="portainer-介绍" tabindex="-1">Portainer 介绍 <a class="header-anchor" href="#portainer-介绍" aria-label="Permalink to “Portainer 介绍”">​</a></h1><p>Portainer 是目前最流行的 Docker 可视化管理工具，提供直观的 Web 界面来管理容器、镜像、网络和数据卷，无需记忆复杂的 Docker 命令。</p><div class="info custom-block"><p class="custom-block-title">官方资源</p><ul><li>官网：<a href="https://www.portainer.io" target="_blank" rel="noreferrer">https://www.portainer.io</a></li><li>文档：<a href="https://docs.portainer.io" target="_blank" rel="noreferrer">https://docs.portainer.io</a></li><li>GitHub：<a href="https://github.com/portainer/portainer" target="_blank" rel="noreferrer">github.com/portainer/portainer</a></li><li>CE vs BE 对比：<a href="https://docs.portainer.io/start/intro" target="_blank" rel="noreferrer">docs.portainer.io/start/intro</a></li></ul></div><h2 id="一、什么是-portainer" tabindex="-1">一、什么是 Portainer <a class="header-anchor" href="#一、什么是-portainer" aria-label="Permalink to “一、什么是 Portainer”">​</a></h2><p>Portainer 本身也是一个运行在 Docker 中的容器，通过挂载 Docker Socket 与 Docker 守护进程通信，实现对 Docker 环境的完整管理。</p><p><strong>核心特点：</strong></p><ul><li>📦 <strong>容器全生命周期管理</strong> — 创建、启动、停止、删除、重启</li><li>🖼️ <strong>镜像管理</strong> — 拉取、删除、推送、构建</li><li>🌐 <strong>网络 &amp; 数据卷管理</strong> — 可视化配置</li><li>📋 <strong>日志实时查看</strong> — 无需 SSH 进服务器</li><li>💻 <strong>Web 终端</strong> — 直接在浏览器中进入容器</li><li>🚀 <strong>Stack（Compose）部署</strong> — 支持 Docker Compose 格式</li></ul><hr><h2 id="二、版本对比" tabindex="-1">二、版本对比 <a class="header-anchor" href="#二、版本对比" aria-label="Permalink to “二、版本对比”">​</a></h2><p>Portainer 提供两个版本：</p><table tabindex="0"><thead><tr><th>特性</th><th>Community Edition (CE)</th><th>Business Edition (BE)</th></tr></thead><tbody><tr><td>价格</td><td><strong>免费</strong></td><td>付费</td></tr><tr><td>开源</td><td>✅</td><td>❌</td></tr><tr><td>单机 Docker 管理</td><td>✅</td><td>✅</td></tr><tr><td>Docker Swarm 管理</td><td>✅</td><td>✅</td></tr><tr><td>Kubernetes 管理</td><td>基础功能</td><td>完整功能</td></tr><tr><td>多用户 &amp; 权限管理</td><td>基础</td><td>高级 RBAC</td></tr><tr><td>审计日志</td><td>❌</td><td>✅</td></tr><tr><td>镜像安全扫描</td><td>❌</td><td>✅</td></tr><tr><td>适合场景</td><td>个人 / 小团队</td><td>企业 / 生产环境</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title custom-block-title-default">TIP</p><p>对于个人开发者和小团队，<strong>CE 版本完全够用</strong>。</p></div><hr><h2 id="三、主要功能详解" tabindex="-1">三、主要功能详解 <a class="header-anchor" href="#三、主要功能详解" aria-label="Permalink to “三、主要功能详解”">​</a></h2><h3 id="_3-1-仪表盘-dashboard" tabindex="-1">3.1 仪表盘（Dashboard） <a class="header-anchor" href="#_3-1-仪表盘-dashboard" aria-label="Permalink to “3.1 仪表盘（Dashboard）”">​</a></h3><p>首页展示当前 Docker 环境的整体状态：</p><ul><li>运行中 / 停止的容器数量</li><li>本地镜像数量</li><li>数据卷和网络数量</li><li>资源使用概览</li></ul><h3 id="_3-2-容器管理" tabindex="-1">3.2 容器管理 <a class="header-anchor" href="#_3-2-容器管理" aria-label="Permalink to “3.2 容器管理”">​</a></h3><table tabindex="0"><thead><tr><th>功能</th><th>说明</th></tr></thead><tbody><tr><td>容器列表</td><td>查看所有容器状态、端口、创建时间</td></tr><tr><td>快速操作</td><td>一键启动 / 停止 / 重启 / 删除</td></tr><tr><td>容器详情</td><td>查看配置、环境变量、挂载信息</td></tr><tr><td>实时日志</td><td>浏览器内查看实时输出日志</td></tr><tr><td>Web 控制台</td><td>直接在浏览器中执行 shell 命令</td></tr><tr><td>统计信息</td><td>CPU、内存、网络 I/O 实时图表</td></tr></tbody></table><h3 id="_3-3-镜像管理" tabindex="-1">3.3 镜像管理 <a class="header-anchor" href="#_3-3-镜像管理" aria-label="Permalink to “3.3 镜像管理”">​</a></h3><ul><li>从 Docker Hub 或私有仓库拉取镜像</li><li>查看镜像层级结构</li><li>删除不用的镜像释放磁盘空间</li><li>导出 / 导入镜像</li></ul><h3 id="_3-4-stack-compose-部署" tabindex="-1">3.4 Stack（Compose 部署） <a class="header-anchor" href="#_3-4-stack-compose-部署" aria-label="Permalink to “3.4 Stack（Compose 部署）”">​</a></h3><p>支持直接在界面中粘贴 <code>docker-compose.yml</code> 内容一键部署多容器应用，等同于 <code>docker compose up -d</code>。</p><h3 id="_3-5-网络管理" tabindex="-1">3.5 网络管理 <a class="header-anchor" href="#_3-5-网络管理" aria-label="Permalink to “3.5 网络管理”">​</a></h3><ul><li>查看所有 Docker 网络</li><li>创建自定义 bridge 网络</li><li>查看网络内的容器连接关系</li></ul><h3 id="_3-6-数据卷管理" tabindex="-1">3.6 数据卷管理 <a class="header-anchor" href="#_3-6-数据卷管理" aria-label="Permalink to “3.6 数据卷管理”">​</a></h3><ul><li>列出所有数据卷</li><li>查看数据卷详情和大小</li><li>删除未使用的数据卷释放空间</li><li>数据卷浏览器（查看卷内文件）</li></ul><hr><h2 id="四、支持的平台" tabindex="-1">四、支持的平台 <a class="header-anchor" href="#四、支持的平台" aria-label="Permalink to “四、支持的平台”">​</a></h2><table tabindex="0"><thead><tr><th>平台</th><th>支持情况</th></tr></thead><tbody><tr><td>Docker 单机</td><td>✅ 完整支持</td></tr><tr><td>Docker Swarm</td><td>✅ 支持</td></tr><tr><td>Kubernetes</td><td>✅ 支持（CE 基础功能）</td></tr><tr><td>Azure ACI</td><td>✅ BE 版支持</td></tr><tr><td>远程 Docker 环境</td><td>✅ 支持多环境管理</td></tr></tbody></table><hr><h2 id="五、技术架构" tabindex="-1">五、技术架构 <a class="header-anchor" href="#五、技术架构" aria-label="Permalink to “五、技术架构”">​</a></h2><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>浏览器</span></span>
<span class="line"><span>  │</span></span>
<span class="line"><span>  │  HTTPS (9443)</span></span>
<span class="line"><span>  ▼</span></span>
<span class="line"><span>Portainer 容器</span></span>
<span class="line"><span>  │</span></span>
<span class="line"><span>  │  挂载 /var/run/docker.sock</span></span>
<span class="line"><span>  ▼</span></span>
<span class="line"><span>Docker 守护进程（dockerd）</span></span>
<span class="line"><span>  │</span></span>
<span class="line"><span>  ├── 容器 A</span></span>
<span class="line"><span>  ├── 容器 B</span></span>
<span class="line"><span>  └── 容器 C</span></span></code></pre></div><p>Portainer 通过 Unix Socket (<code>/var/run/docker.sock</code>) 与 Docker 守护进程通信，等同于在命令行执行 <code>docker</code> 命令，但提供了图形化界面。</p><hr><h2 id="六、与同类工具对比" tabindex="-1">六、与同类工具对比 <a class="header-anchor" href="#六、与同类工具对比" aria-label="Permalink to “六、与同类工具对比”">​</a></h2><table tabindex="0"><thead><tr><th>工具</th><th>优点</th><th>缺点</th><th>官网</th></tr></thead><tbody><tr><td><strong>Portainer</strong></td><td>功能全面、界面友好、开箱即用</td><td>占用一个容器</td><td><a href="https://www.portainer.io" target="_blank" rel="noreferrer">portainer.io</a></td></tr><tr><td>Lazydocker</td><td>终端 TUI，轻量</td><td>需要 SSH 访问</td><td><a href="https://github.com/jesseduffield/lazydocker" target="_blank" rel="noreferrer">github.com/jesseduffield/lazydocker</a></td></tr><tr><td>Yacht</td><td>界面简洁</td><td>功能相对少</td><td><a href="https://yacht.sh" target="_blank" rel="noreferrer">yacht.sh</a></td></tr><tr><td>Docker Desktop</td><td>官方工具，适合本地开发</td><td>不适合服务器</td><td><a href="https://www.docker.com/products/docker-desktop/" target="_blank" rel="noreferrer">docker.com/products/docker-desktop</a></td></tr></tbody></table><hr><h2 id="七、官方资源" tabindex="-1">七、官方资源 <a class="header-anchor" href="#七、官方资源" aria-label="Permalink to “七、官方资源”">​</a></h2><ul><li>官网：<a href="https://www.portainer.io" target="_blank" rel="noreferrer">https://www.portainer.io</a></li><li>GitHub：<a href="https://github.com/portainer/portainer" target="_blank" rel="noreferrer">https://github.com/portainer/portainer</a></li><li>文档：<a href="https://docs.portainer.io" target="_blank" rel="noreferrer">https://docs.portainer.io</a></li></ul>`,40)])])}const k=r(o,[["render",i]]);export{b as __pageData,k as default};
